window.kbPageData["views/practice/s-38dece0b54a49be3"] = {"key":"practice/s-38dece0b54a49be3","state":{"route":"practice/s-38dece0b54a49be3"},"tree":"<a data-toc-link href=\"#skills/shenlun\">申论技能首页</a><details data-branch=\"module-归纳概括\"><summary>归纳概括</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-c898afc5816920c2\">概括作用与成效</a><a data-toc-link href=\"#practice/s-0b47c7faa1dcfbc7\">提炼做法与经验</a><a data-toc-link href=\"#practice/s-75a1eb1e46268fd8\">归类概括材料中的问题</a><a data-toc-link href=\"#practice/s-4863baf2b4febcf4\">配对概括做法与成效</a><a data-toc-link href=\"#practice/s-c94c813ed743298a\">从材料提取概念特征</a><a data-toc-link href=\"#practice/s-4da331cba0998f2b\">分条梳理不同立场与分歧</a></div></details><details data-branch=\"module-综合分析\"><summary>综合分析</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-43e39afd29a17e74\">解释含义与作用</a><a data-toc-link href=\"#practice/s-599008555ed60dda\">分析现象形成的原因</a><a data-toc-link href=\"#practice/s-93367fee5c934df6\">从案例推导改进建议</a></div></details><details data-branch=\"module-提出对策\"><summary>提出对策</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-c6bd983baf5dd3ae\">根据问题成因逐项提出措施</a><a data-toc-link href=\"#practice/s-ecba3f8c2c1d3b9b\">将外地经验转化为本地措施</a><a data-toc-link href=\"#practice/s-9b570af6b9f113ee\">按治理环节组织对策</a><a data-toc-link href=\"#practice/s-91888cb77ec12615\">从材料反馈中提炼改进建议</a></div></details><details data-branch=\"module-应用文写作\" open><summary>应用文写作</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-171ebed39b4fe1cf\">汇报与交流发言</a><a data-toc-link href=\"#practice/s-b92b682e65d12042\">面向公众动员参与</a><a data-toc-link href=\"#practice/s-cabc6af5d656b214\">宣传介绍与活动报道</a><a data-toc-link href=\"#practice/s-5cd530a611f08110\">编写案例摘要</a><a data-toc-link href=\"#practice/s-9f175b7eb1a79028\">陈述事由与请求</a><a data-toc-link href=\"#practice/s-38dece0b54a49be3\" aria-current=\"page\">拟定工作事项与措施</a><a data-toc-link href=\"#practice/s-c8dfde3ede3eadab\">撰写案例短评或点评</a></div></details><details data-branch=\"module-文章写作\"><summary>文章写作</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-b8139af04b609dce\">展开分论点的论证</a><a data-toc-link href=\"#practice/s-4fdadcb77809c673\">围绕中心论点组织分论点</a><a data-toc-link href=\"#practice/s-ab43045e4cab9ffe\">从材料立意并确立中心论点</a></div></details>","packs":{"国考 2025 行政执法 申论#3":"839a50dcce2144ab61cc34c9","国考 2024 地市级 申论#3":"eebd63422b979034fa982ba1"},"questions":{"国考 2025 行政执法 申论#3":{"paper":"国考 2025 行政执法 申论","n":3,"mod":"申论","src":["dbb2469ea58338709f40.pdf",4],"asrc":["d1fc3fe21ef6ae3b1ae6.pdf",2]},"国考 2024 地市级 申论#3":{"paper":"国考 2024 地市级 申论","n":3,"mod":"申论","src":["a79e2681008a994c88a1.pdf",4],"asrc":["a3a840c0e3e8755b8daa.pdf",2]}},"first":{"qs":{"国考 2025 行政执法 申论#3":{"paper":"国考 2025 行政执法 申论","n":3,"mod":"申论","src":["dbb2469ea58338709f40.pdf",4],"asrc":["d1fc3fe21ef6ae3b1ae6.pdf",2],"m":["09ab9fc694b55146"],"task":"根据材料3，将夜市巡查记录归纳为工作事项，并逐项写明检查对象、现场处置方式和收尾要求，形成500字以内的工作指南。","current_affairs":{"state":"否","event":null,"year":null,"basis":"作答依据是材料内的大帆夜市巡查案例及其操作要求，无需掌握窗口内的外部事件或政策部署。"},"links":[{"id":"k-e12589bf1bcfff1e","label":"夜市摊位消防安全巡查要求","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"材、防火标志、疏散通道、安全出口、消防通道、用电安全等。","why":"指南须写明消防设施器材、防火标志、疏散与消防通道以及用电安全等检查项目。","origin":"逐题标记"},{"id":"k-ff6e88fe46dcb954","label":"夜市食品安全巡查要求","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"和经手人员等情况，检查食品卫生许可证、从业人员健康证。","why":"指南须写明食品存放、加工、经手人员和相关证照的检查要求。","origin":"逐题标记"},{"id":"k-81c3863e4f1f33fe","label":"夜市巡查发现隐患后的取证与限期整改","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"平台，并对摊主进行批评教育，责令限期改正。","why":"发现问题后须登记、拍照上传平台，并对摊主进行教育、督促限期改正。","origin":"逐题标记"},{"id":"k-c76a2d6f2250fc77","label":"夜市人流密集路段巡控与拥堵疏导","catalog_id":null,"type":"方法与技能","role":"直接考查","field":"answer","quote":"大的街口，利用警用无人机进行路面巡控；关注信息平台通知，出现交通拥堵问题时，及时赶赴现场疏导。","why":"指南须写明如何巡控人流密集路段，以及接到拥堵通知后的现场处置。","origin":"逐题标记"},{"id":"k-3ed2aa2ea30d417a","label":"夜市现场纠纷分级调解","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"小纠纷现场调解，较大纠纷将当事人带到调解室解决","why":"纠纷发生后先疏散围观群众，再按纠纷大小安排现场调解或调解室调解。","origin":"逐题标记"},{"id":"k-a1cd076ec5ca8eb5","label":"夜市巡查发现走散人员后的安置与联络","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"人员走散，送至夜市综合服务办公室，及时联系家属。","why":"指南须明确走散人员的临时安置地点和家属联络要求。","origin":"逐题标记"},{"id":"k-e2e1a601abeb3d3b","label":"通过反诈体检识别并提醒高风险人群","catalog_id":null,"type":"方法与技能","role":"直接考查","field":"answer","quote":"开展“反诈体检”，测试理财投资习惯、金融知识、常用社交软件等信息，重点提醒高风险易受损群体。","why":"指南须将收集相关信息、识别高风险人群和重点提醒列入反诈宣讲工作。","origin":"逐题标记"},{"id":"k-aede726fc5de53a1","label":"夜市巡查结束后的记录与交接","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"M1","quote":"完成当天的巡查记录，做好工作交接。","why":"巡查结束后须记录当天工作情况并完成交接。","origin":"逐题标记"},{"id":"s-38dece0b54a49be3","label":"将按时间叙述的工作记录归纳为事项与操作要求","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"请你草拟该指南中的工作事项及其相应工作内容。","why":"需要按工作目的归并分散在各时点的巡查记录，并在对应事项下提炼具体检查与处置要求。","origin":"逐题标记","originalId":"s-493c364b674ed9ea","additionalEvidence":[{"id":"s-38dece0b54a49be3","label":"按使用对象写工作指南","catalog_id":"1145b945bfee41b8","type":null,"role":"原有题组","field":"group","quote":"把现场工作拆成步骤","why":"原训练目录收录于该题组。","origin":"技能点库"}]}],"stem":"为使夜市管理工作更加规范，B市大帆夜市综合服务办公室计划编写一份“平安夜市安全巡查工作指南”，供工作人\n员使用。根据“给定资料3”，请你草拟该指南中的工作事项及其相应工作内容。（20分）\n要求：\n（1）紧扣资料，内容全面；\n（2）工作事项明确，工作内容具体；\n（3）层次分明，条目清晰，语言简洁；\n（4）不超过500字。","options":[],"answer":"","analysis":"事项一：19点开始，对各商铺、摊位逐一进行消防卫生巡查。工作内容：1.检查消防安全情况。包括消防设施器\n材、防火标志、疏散通道、安全出口、消防通道、用电安全等。2.检查食品安全卫生情况。查看食品存放、加工过程\n和经手人员等情况，检查食品卫生许可证、从业人员健康证。3.现场处理。发现问题及时登记记录、手机拍照、上传\n平台，并对摊主进行批评教育，责令限期改正。\n  事项二：消防卫生巡查结束后直至夜市打烊前，来回巡逻，维持夜市秩序。工作内容：1.维护交通秩序。在人流\n大的街口，利用警用无人机进行路面巡控；关注信息平台通知，出现交通拥堵问题时，及时赶赴现场疏导。2.加强治\n安防控。遇到矛盾纠纷及时赶赴现场，疏散围观群众，小纠纷现场调解，较大纠纷将当事人带到调解室解决；遇到\n人员走散，送至夜市综合服务办公室，及时联系家属。\n  事项三：21点开始，在“平安驿站”进行安全知识宣讲。工作内容：宣讲常规安全知识；宣讲电信诈骗防范知识，\n开展“反诈体检”，测试理财投资习惯、金融知识、常用社交软件等信息，重点提醒高风险易受损群体。\n  事项四：夜市打烊后，进行巡查工作收尾。工作内容：根据当天工作情况，完成巡查记录，做好交接工作。\n  参考答案说明：本参考答案按照“工作事项+工作内容”的形式，从“消防卫生巡查”“维持夜市秩序”“安全知识宣\n讲”“巡查工作收尾”四个方面展开，各条答案要点之间在内容上相互并列，没有交叉。","figs":[],"state":"已标记","notes":[],"domains":["社会治理","公共管理"],"nature":"综合题","current":false}},"materialFiles":{"09ab9fc694b55146":"43a86f7eb52af29ac8f2b6cc"},"terms":{"k-e12589bf1bcfff1e":{"id":"k-e12589bf1bcfff1e","mode":"k","type":"制度与规则","title":"大帆夜市消防巡查","qs":[],"count":1},"k-ff6e88fe46dcb954":{"id":"k-ff6e88fe46dcb954","mode":"k","type":"制度与规则","title":"大帆夜市食品安全巡查","qs":[],"count":1},"k-81c3863e4f1f33fe":{"id":"k-81c3863e4f1f33fe","mode":"k","type":"制度与规则","title":"大帆夜市巡查问题记录与限期整改","qs":[],"count":1},"k-c76a2d6f2250fc77":{"id":"k-c76a2d6f2250fc77","mode":"k","type":"方法与技能","title":"大帆夜市交通巡控与拥堵疏导","qs":[],"count":1},"k-3ed2aa2ea30d417a":{"id":"k-3ed2aa2ea30d417a","mode":"k","type":"制度与规则","title":"大帆夜市纠纷分级调解","qs":[],"count":1},"k-a1cd076ec5ca8eb5":{"id":"k-a1cd076ec5ca8eb5","mode":"k","type":"制度与规则","title":"大帆夜市走散人员安置与联络","qs":[],"count":1},"k-e2e1a601abeb3d3b":{"id":"k-e2e1a601abeb3d3b","mode":"k","type":"方法与技能","title":"大帆夜市“反诈体检”","qs":[],"count":1},"k-aede726fc5de53a1":{"id":"k-aede726fc5de53a1","mode":"k","type":"制度与规则","title":"大帆夜市巡查记录与交接","qs":[],"count":1},"s-38dece0b54a49be3":{"id":"s-38dece0b54a49be3","mode":"s","type":"应用文写作","title":"拟定工作事项与措施","qs":[],"count":2}},"questions":{}},"firstMaterials":[{"key":"09ab9fc694b55146","value":["材料3","材料3\n  夜市，管好了就是十里飘香的美食街区，稍有松懈，就可能变成一失万无的安全事故区。为打造“平安夜市”，B\n市公安局大帆分局联合相关部门成立了大帆夜市综合服务办公室，制定了严格的安全管理规定，组成了一支由公\n安、城管、市场监管和街道办事处工作人员构成的管理队伍，分组定时进行巡查。\n  19:00，平安夜市安全巡查第三小组在组长小葛带领下，一行四人从夜市街口开始，展开当天的安全巡查。\n  19:10，巡查小组发现夜市某摊位只有一瓶灭火器。“每个摊位最少配备两瓶灭火器，摊主必须会使用灭火\n器。”为了让烧烤摊的“烟火气”更安全，综合服务办公室要求夜市经营场地必须具备消防安全条件，配置消防设施、\n器材，保障疏散通道、安全出口、消防车通道畅通，设置防火标志。巡查小组对摊主进行了消防安全教育，并责令\n其限期改正。\n  19:40，巡查小组已经检查了10余户商铺的用电安全情况，并已逐一检查排烟管道是否有破损、食品卫生许可证\n是否悬挂到位……对存在问题的地方，小葛用手机拍照，上传到了市场管理平台。在市场入口处管理大屏上，各摊\n点实时安全卫生情况一览无遗。商户的库房装有摄像头，巡查小组可以随时查看库房的食品存放、加工过程和经手\n人员等情况。\n   19:50，巡查小组发现烧烤摊主王某存在从业人员健康证过期问题，做了记录登记，并对其批评教育，要求其尽\n快更换健康证。\n   20:00，巡查小组发现摊主翟某存在生熟、干湿、鲜活食品未分开储存等问题。为规范夜市食品摊贩经营行为，\n保障消费者“舌尖上的安全”，依据有关法律法规，此前夜市综合服务办公室已经专门发布了夜市食品安全告诫提示。\n根据相关规定，巡查小组中来自市场监管局的老张对翟某开具了限期整改通知书。\n   20:15，巡查小组接到综合服务中心信息平台通知，夜市中段有车辆违规停留，阻塞交通并造成了人流拥挤。巡\n查小组及时赶到现场进行交通疏导。针对夜市人流大、治安复杂的情况，夜市中心街道设立了大型显示屏，主干道\n上配备了10余个“云”广播，每个商铺配备口哨，可达到一呼百应、群防群治效果。在人流量大的街道口，发挥警用无\n人机高空视野广、监控范围大、视角灵活多变优势，深度融合警务指挥体系，实时联动街边警力，让路面巡控更高\n效。\n   20:30，夜市中有两名顾客因抢占座位问题而引发纠纷，并有大量群众围观。巡查小组及时赶到现场后，疏散了\n围观群众，对当事人进行现场问询，避免了矛盾进一步激化。之后，将其带至夜市综合服务办公室调解室。“大家相\n互握个手，继续开心吃烧烤，这个事情就让它过去好了。”在调解室内，民警、调解员、律师一起，成功调解了这起\n纠纷。“警察同志，这里的秤不太准”、“这边的摊位应该是我的，他摆过界了”、“刚在这家店买的东西不太新鲜”……\n尽管类似的纠纷时有发生，但都能及时得到妥善处置。对于小的纠纷，巡查小组一般现场加以调解，及时化解矛\n盾；对于较大的纠纷，则将当事人带到调解室专门解决。\n   20:50，巡查小组发现一名和家长走散的儿童。在及时联系家长后，巡查小组中的社区民警老皮将孩子送到了夜\n市综合服务办公室。“我们巡查小组每天来回巡逻夜市，维持市场秩序，最多一天走了4万多步，要让夜市平安，可不\n容易嘞。”老皮感慨地说。\n   21:00，巡查小组在夜市“平安驿站”进行安全知识宣讲。“这几种常见的新型诈骗，注意防范”、“酒后千万不要开\n车”、“我们就在附近巡逻，有问题随时找我们”、“不要打架，打输住院，打赢坐牢”。“平安驿站”也是居民和游客经常\n光顾的地方。防范电信诈骗是“平安驿站”里的重头戏，巡查小组一改过去“单向灌输”的宣传模式，把理财投资习惯、\n\n金融知识测试、常用社交软件等都纳入“反诈体检”项目。作为对投资理财有“高期盼”的“金融小白”，俞女士被列入高\n风险易受损群体。“真没想到，逛夜市还能收获安全防范知识，你们的宣传太接地气了。”又惊又喜的俞女士说道。\n  夏季，夜市一般到凌晨1点才会“降温”，周末和节假日则会更晚。夜市打烊了，巡查小组却不一定能“打烊”。每晚\n例行巡查结束后，他们还要完成当天的巡查记录，做好工作交接。小葛笑着说：“希望通过我们的绵薄之力，让前来\n消费的市民游客安心，也让这些商户放心做生意。”",["dbb2469ea58338709f40.pdf",2]],"label":"国考 2025 行政执法 申论|材料3"}],"node":{"id":"s-38dece0b54a49be3","mode":"s","title":"拟定工作事项与措施","type":"应用文写作","domain":"申论方法","reading":"","intro":"","priority":100,"aliases":["按使用对象写工作指南","将按时间叙述的工作记录归纳为事项与操作要求","按政策依据、建设目标和实施措施归类材料要点","组织实施意见的目标与措施"],"qs":["国考 2024 地市级 申论#3","国考 2025 行政执法 申论#3"],"current":false,"candidates":false,"legacySkill":"1145b945bfee41b8","trainingGroups":[{"name":"把现场工作拆成步骤","ids":["国考 2025 行政执法 申论#3"]},{"name":"把服务职责写成可执行条目","ids":[]}],"basisGroup":"","authority":null,"sourceOnly":false,"method":"从工作目标倒推要做的事项，把材料中的经验写成执行者可以落实的措施。","subject":"申论","directorySummary":"先确定谁拿着指南做事。将材料整理为工作事项，每项写清什么时候做、做什么、如何交接或记录，让使用者能逐条照做。","sources":[{"id":"1145b945bfee41b8","label":"按使用对象写工作指南","topic":"申论方法","category":"非时政","text":"先确定谁拿着指南做事。将材料整理为工作事项，每项写清什么时候做、做什么、如何交接或记录，让使用者能逐条照做。","source":{"doc":"d1fc3fe21ef6ae3b1ae6","first":2,"last":2,"file":"d1fc3fe21ef6ae3b1ae6.pdf","page":2},"basis":"据题目与解析整理"}],"publishedSets":[{"name":"把现场工作拆成步骤","ids":["国考 2025 行政执法 申论#3"],"units":[["国考 2025 行政执法 申论#3"]]},{"name":"其余同技能题目","ids":["国考 2024 地市级 申论#3"],"units":[["国考 2024 地市级 申论#3"]]}]}};
